//! Shared local UI design system. Content is authored by the application, not user input.
//! Avoid inserting unescaped dynamic values into HTML templates.
use axum::response::Html;

const STYLE: &str = ":root{color-scheme:light;--bg:#f5f6f4;--surface:#fff;--text:#202824;--muted:#69756d;--line:#e0e6e0;--accent:#266b56;--accent-hover:#18523f;--accent-soft:#e3f0e9;--danger:#b74141;--shadow:0 10px 32px rgba(28,43,31,.055);--radius:18px;--focus:#9ed1b5;font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;font-synthesis:none}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-size:15px;line-height:1.6;transition:background .25s,color .25s}body[data-theme=dark]{color-scheme:dark;--bg:#121b18;--surface:#1c2722;--text:#e9efeb;--muted:#a0afa5;--line:#34423a;--accent:#9cd3ae;--accent-hover:#c2e7cb;--accent-soft:#2a4234;--danger:#ff9696;--shadow:0 12px 35px rgba(0,0,0,.13)}body[data-theme=contrast]{color-scheme:dark;--bg:#080a09;--surface:#141816;--text:#fff;--muted:#d0ded4;--line:#717d75;--accent:#a9ffbc;--accent-hover:#f0ffb8;--accent-soft:#172c20;--danger:#ffaaaa;--shadow:none}a{color:var(--accent);text-underline-offset:3px}a:hover{text-decoration-thickness:2px}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}button,.button{display:inline-flex;align-items:center;justify-content:center;gap:.45rem;border:1px solid transparent;background:var(--accent);color:var(--bg);border-radius:11px;padding:.71rem 1.05rem;font-weight:650;line-height:1.25;text-decoration:none;min-height:44px;transition:transform .16s,background .16s,box-shadow .16s}button:hover:not(:disabled),.button:hover{background:var(--accent-hover);transform:translateY(-1px)}button:active:not(:disabled){transform:translateY(0)}button.secondary,.button.secondary{background:var(--surface);color:var(--text);border-color:var(--line)}button.secondary:hover,.button.secondary:hover{background:var(--accent-soft)}button.danger{background:transparent;color:var(--danger);border-color:var(--line)}:focus-visible{outline:3px solid var(--focus);outline-offset:3px}input,textarea,select{background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:11px;padding:.72rem .84rem;outline:0;min-height:44px;width:100%;transition:border .17s,box-shadow .17s}input:focus,textarea:focus,select:focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}textarea{resize:vertical;min-height:110px}label{display:grid;gap:.35rem;font-weight:560;font-size:.9rem}input[type=checkbox]{width:18px;height:18px;min-height:18px;accent-color:var(--accent)}label:has(input[type=checkbox]){display:flex;align-items:center}form{display:grid;gap:1.05rem}form button{justify-self:start}p{margin:.45rem 0 1.15rem}h1,h2,h3{line-height:1.18;letter-spacing:-.035em}h1{font-size:clamp(2rem,4vw,2.85rem);margin:.15rem 0 1rem;font-weight:720}h2{font-size:1.18rem;margin:0 0 1.1rem}h3{font-size:1rem}small,.hint{color:var(--muted)}.shell{max-width:1190px;margin:0 auto;padding:0 28px}.site-header{background:var(--surface);border-bottom:1px solid var(--line)}.header-inner{min-height:78px;display:flex;align-items:center;gap:26px;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;color:var(--text);text-decoration:none;font-weight:750;letter-spacing:-.025em;white-space:nowrap}.brand-mark{width:37px;height:37px;background:var(--accent);color:var(--bg);border-radius:12px;display:grid;place-items:center;font-weight:800;font-size:1.2rem}.nav{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.nav a{color:var(--muted);border-radius:9px;padding:9px 12px;text-decoration:none;font-weight:530;font-size:.9rem}.nav a:hover,.nav a[aria-current=page]{background:var(--accent-soft);color:var(--accent)}.header-actions{display:flex;align-items:center;gap:8px}.theme-picker{width:auto;min-height:36px;padding:6px 24px 6px 10px;font-size:.83rem}.page{padding-top:58px;padding-bottom:90px}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:.73rem;font-weight:750;color:var(--accent);margin-bottom:12px}.lead{font-size:1.07rem;color:var(--muted);max-width:60ch}.page-heading{margin-bottom:31px}.columns{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);gap:20px;align-items:start}.grid-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.panel,section.card{padding:29px;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.panel p:last-child{margin-bottom:0}.stack{display:grid;gap:18px}.muted{color:var(--muted)}.notice{padding:13px 15px;background:var(--accent-soft);border-radius:12px;color:var(--text);margin:15px 0}.status{min-height:24px;font-weight:580;color:var(--accent);margin:8px 0}.status[data-error=true]{color:var(--danger)}.segmented{display:flex;padding:4px;background:var(--accent-soft);border-radius:12px;gap:4px;margin:0 0 22px}.segmented button{background:transparent;border:0;flex:1;color:var(--muted);padding:10px}.segmented button[aria-selected=true]{background:var(--surface);color:var(--text);box-shadow:var(--shadow)}.view[hidden]{display:none!important}.item{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid var(--line)}.item:last-child{border-bottom:0}.item-title{font-weight:680}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.85rem;overflow-wrap:anywhere}.pill{display:inline-flex;font-size:.73rem;font-weight:680;padding:3px 10px;border-radius:100px;color:var(--accent);background:var(--accent-soft)}.toolbar{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;margin-bottom:20px}.empty{padding:35px 16px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:13px}.foot{border-top:1px solid var(--line);padding:27px 0;font-size:.82rem;color:var(--muted)}.foot .shell{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}@media(max-width:760px){.shell{padding:0 18px}.header-inner{flex-wrap:wrap;padding:14px 0;gap:12px}.nav{order:3;width:100%;overflow:auto;flex-wrap:nowrap}.nav a{white-space:nowrap}.page{padding-top:34px}.columns,.grid-two{grid-template-columns:1fr}.panel{padding:21px}.theme-picker{max-width:135px}}@media(prefers-reduced-motion:no-preference){.panel{animation:enter .36s both}@keyframes enter{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}";
const SCRIPT: &str = "(()=>{const select=document.querySelector('[data-theme-picker]');const stored=localStorage.getItem('auth-theme');const preference=stored||'system';select.value=preference;function apply(mode){const dark=matchMedia('(prefers-color-scheme:dark)').matches;document.body.dataset.theme=mode==='system'?(dark?'dark':'light'):mode;}apply(preference);select.addEventListener('change',()=>{localStorage.setItem('auth-theme',select.value);apply(select.value)});matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(select.value==='system')apply('system')})})();";

pub fn render(title: &str, area: &str, body: &str) -> Html<String> {
    let nav = [
        ("Compte", "/account"),
        ("Applications liées", "/account/permissions"),
        ("Développeur", "/developer"),
    ];
    let mut links = String::new();
    for (name, href) in nav {
        let current = if area == href {
            " aria-current=\"page\""
        } else {
            ""
        };
        links.push_str(&format!("<a href=\"{href}\"{current}>{name}</a>"));
    }
    Html(format!(
        r####"<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><meta name="theme-color" content="#f5f6f4"><title>{title} · Donnarieix Auth</title><style>{STYLE}</style></head><body><header class="site-header"><div class="shell header-inner"><a class="brand" href="/account"><span class="brand-mark" aria-hidden="true">D</span><span>Donnarieix <strong>Auth</strong></span></a><nav class="nav" aria-label="Navigation principale">{links}</nav><div class="header-actions"><label class="hint" for="theme-picker">Thème</label><select id="theme-picker" class="theme-picker" data-theme-picker aria-label="Thème de l'interface"><option value="system">Système</option><option value="light">Clair</option><option value="dark">Sombre</option><option value="contrast">Contraste</option></select></div></div></header><main class="shell page">{body}</main><footer class="foot"><div class="shell"><span>Donnarieix Auth · Identité sous votre contrôle</span><span>Connexion locale sécurisée · <a href="/.well-known/openid-configuration">OpenID Connect</a></span></div></footer><script>{SCRIPT}</script></body></html>"####
    ))
}
